use std::collections::HashMap;
use std::sync::{Arc, Mutex};

// Feature flag configuration
#[derive(Clone, Debug)]
pub struct FeatureFlags {
    pub enable_custom_templates: bool,
    pub enable_debug_mode: bool,
    pub template_cache_enabled: bool,
    pub max_template_depth: usize,
}

impl Default for FeatureFlags {
    fn default() -> Self {
        FeatureFlags {
            enable_custom_templates: false,
            enable_debug_mode: false,
            template_cache_enabled: true,
            max_template_depth: 3,
        }
    }
}

// Template engine with variable substitution
pub struct TemplateEngine {
    flags: FeatureFlags,
    cache: Arc<Mutex<HashMap<String, String>>>,
    builtins: HashMap<String, String>,
}

impl TemplateEngine {
    pub fn new(flags: FeatureFlags) -> Self {
        let mut builtins = HashMap::new();
        builtins.insert("app_name".to_string(), "MyApp".to_string());
        builtins.insert("version".to_string(), "2.1.0".to_string());
        builtins.insert("env".to_string(), "production".to_string());
        TemplateEngine {
            flags,
            cache: Arc::new(Mutex::new(HashMap::new())),
            builtins,
        }
    }

    // Resolve a variable reference from context or builtins
    fn resolve_var(&self, key: &str, context: &HashMap<String, String>) -> Option<String> {
        // Only resolve from allowed builtin keys - never from user context for builtins
        if self.builtins.contains_key(key) {
            self.builtins.get(key).cloned()
        } else {
            context.get(key).cloned()
        }
    }

    // Core rendering: substitutes {{var}} patterns - single pass only
    fn render_pass(&self, template: &str, context: &HashMap<String, String>) -> String {
        let mut result = String::new();
        let mut chars = template.chars().peekable();
        while let Some(c) = chars.next() {
            if c == '{' {
                if chars.peek() == Some(&'{') {
                    chars.next();
                    let mut var_name = String::new();
                    while let Some(&nc) = chars.peek() {
                        if nc == '}' {
                            chars.next();
                            if chars.peek() == Some(&'}') {
                                chars.next();
                            }
                            break;
                        }
                        var_name.push(nc);
                        chars.next();
                    }
                    let trimmed = var_name.trim();
                    // Only allow alphanumeric and underscore in variable names
                    if trimmed.chars().all(|c| c.is_alphanumeric() || c == '_') {
                        if let Some(val) = self.resolve_var(trimmed, context) {
                            // HTML-escape the resolved value to prevent injection
                            result.push_str(&html_escape(&val));
                        } else {
                            result.push_str("");
                        }
                    } else {
                        result.push_str("");
                    }
                } else {
                    result.push(c);
                }
            } else {
                result.push(c);
            }
        }
        result
    }

    // Public render API - applies feature flag logic, single pass only
    pub fn render(&self, template_key: &str, user_template: Option<&str>, context: &HashMap<String, String>) -> Result<String, String> {
        let template_source = if let Some(ut) = user_template {
            // Feature flag gate: custom templates require flag
            if !self.flags.enable_custom_templates {
                return Err("Custom templates are disabled".to_string());
            }
            self.sanitize_template(ut)?
        } else {
            self.get_system_template(template_key)?
        };

        // No caching of user-supplied templates to prevent cache poisoning
        // Single-pass render only - no recursive expansion
        let result = self.render_pass(&template_source, context);

        Ok(result)
    }

    // Strict sanitization: only allow simple variable references
    fn sanitize_template(&self, input: &str) -> Result<String, String> {
        // Limit template length
        if input.len() > 1024 {
            return Err("Template too long".to_string());
        }
        // Block any patterns that aren't simple text + {{varname}}
        let blocked = ["exec", "system", "eval", "import", "require", "__", "..", "//"];
        let lower = input.to_lowercase();
        for b in &blocked {
            if lower.contains(b) {
                return Err(format!("Blocked pattern: {}", b));
            }
        }
        Ok(input.to_string())
    }

    fn get_system_template(&self, key: &str) -> Result<String, String> {
        match key {
            "greeting" => Ok("Hello, {{username}}! Welcome to {{app_name}} v{{version}}".to_string()),
            "status" => Ok("Service {{app_name}} running in {{env}} mode".to_string()),
            _ => Err(format!("Unknown template: {}", key)),
        }
    }
}

fn html_escape(input: &str) -> String {
    input
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#x27;")
}

// Request handler simulating REST endpoint
pub fn handle_render_request(
    engine: &TemplateEngine,
    template_key: &str,
    user_template: Option<&str>,
    user_context: HashMap<String, String>,
) -> Result<String, String> {
    // The context is built from user input plus system defaults
    let mut context = HashMap::new();
    context.insert("username".to_string(), "guest".to_string());
    // User-supplied context values override defaults (but resolve_var prioritizes builtins)
    for (k, v) in user_context {
        context.insert(k, v);
    }
    engine.render(template_key, user_template, &context)
}

// Feature flag loader - in production reads from config service
pub fn load_feature_flags_from_env() -> FeatureFlags {
    let mut flags = FeatureFlags::default();
    if std::env::var("ENABLE_CUSTOM_TEMPLATES").unwrap_or_default() == "1" {
        flags.enable_custom_templates = true;
    }
    if std::env::var("ENABLE_DEBUG").unwrap_or_default() == "1" {
        flags.enable_debug_mode = true;
    }
    // Debug mode does NOT affect template depth - security invariant
    flags
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_render() {
        let flags = FeatureFlags::default();
        let engine = TemplateEngine::new(flags);
        let ctx = HashMap::new();
        let result = engine.render("greeting", None, &ctx).unwrap();
        assert!(result.contains("guest"));
    }

    #[test]
    fn test_custom_template_blocked_without_flag() {
        let flags = FeatureFlags::default();
        let engine = TemplateEngine::new(flags);
        let ctx = HashMap::new();
        let result = engine.render("x", Some("Hello {{username}}"), &ctx);
        assert!(result.is_err());
    }
}
